// Status: "looks good to me" from the author, not reviewed yet.
//
// Contract
//   toggle(productId)  adds/removes a product; the UI updates immediately, then the change is
//                      synced with api.put("/wishlist/:id", { wished }).
//   ids / count / isWished(id) / wishedProducts   current wishlist
//   error              message to show when a sync failed (null otherwise)
import { useCallback, useState } from "react";
import api from "../api/axios";
import { products } from "../data/products";

export default function useWishlist() {
  const [ids, setIds] = useState([]);
  const [error, setError] = useState(null);

  const toggle = useCallback(async (productId) => {
    const wished = ids.includes(productId);
    const next = wished ? ids.filter((id) => id !== productId) : [...ids, productId];

    // optimistic update
    setIds(next);

    try {
      await api.put("/wishlist/" + productId, { wished: !wished });
      setError(null);
    } catch (err) {
      console.error("Wishlist sync failed", err);
    }
  }, []);

  const isWished = (productId) => ids.includes(productId);
  const wishedProducts = ids.map((id) => products.find((p) => p._id === id)).filter(Boolean);

  return { ids, count: ids.length, isWished, toggle, wishedProducts, error };
}
